/* 转账卡片主体 */
.msg-transfer-card {
    width: 262px !important;
    height: 93px !important;
    position: relative !important;
    padding: 7px 16px !important;
    margin: 0 auto!important;
    background: var(--transfer-card-bg) !important;
    color: var(--transfer-me-amount-color) !important;
    border: none !important;
    border-radius: 4px !important;
    box-shadow: none !important;
    overflow: visible !important;
}
.msg-transfer-card::before {
    content: "" !important;
    position: absolute !important;
    top: 15px !important;
    right: -3.5px !important;
    width: 8px !important;
    height: 8px !important;
    border: 0 !important;
    border-radius: 1.2px !important;
    transform: rotate(45deg) !important;
    background: inherit !important;
}
.msg-them .msg-transfer-card::before {
    left: -3px !important;
}
.msg-transfer-card::after {
    content: var(--transfer-text-pending-me) !important;
    position: absolute !important;
    top: 37px !important;
    left: 25% !important;
    font-size: 13px !important;
    color: var(--transfer-me-amount-color) !important;
}
.msg-them .msg-transfer-card::after {
    content: var(--transfer-text-pending-them) !important;
}
.msg-transfer-card.msg-transfer-success::after {
    content: var(--transfer-text-success-me) !important;
}
.msg-them .msg-transfer-card.msg-transfer-success::after {
    content: var(--transfer-text-success-them) !important;
}
.msg-transfer-card.msg-transfer-rejected::after {
    content: var(--transfer-text-rejected-me) !important;
}
.msg-them .msg-transfer-card.msg-transfer-rejected::after {
    content: var(--transfer-text-rejected-them) !important;
}
.msg-transfer-card.msg-transfer-expired-card::after {
    content: var(--transfer-text-expired) !important;
}
/* 图标 */
.msg-transfer-icon {
    content: "";
    position: absolute;
    top: 10px !important; 
    left: 10px;
    width: 48px;
    height: 48px; 
    border-radius: 0;
    background-image: url('https://i.postimg.cc/j5CqLH5J/wu-biao-ti38-20260205143013.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    color: transparent !important;
}
/* 标题区域 */
.msg-transfer-label {
    color: transparent !important;
}
/* 金额区域 */
.msg-transfer-amount {
    display: block !important;
    text-align: left !important;
    font-size: var(--transfer-text-size) !important;
    margin-left: 28px !important;
    margin-top: -42px !important;
}
 .msg-transfer-amount span::after {
  content: ".00" !important;
  font-size: var(--transfer-text-size) !important;
}
/* 底部状态文字 */
.msg-transfer-status-text {
    position: relative !important;
    display: block !important;
    width: 100% !important;
    height: 0 !important;
    background: transparent !important;
    padding: 0 !important;
    margin: -12px 0 0 -7px !important;
    color: transparent !important;
    border: none !important;
}
.msg-transfer-status-text::before {
    content: "转账";
    position: absolute;
    display: block;
    color: var(--transfer-text-color);
    font-size: 12px;
    font-weight: var(--font-weight);
    left: -19px;
    opacity: 0.8;
}
.msg-transfer-dot, 
.msg-transfer-divider, 
.msg-transfer-subtitle,
.msg-transfer-chevron, 
.msg-transfer-check,
.msg-transfer-expiry{
  display: none !important;
}
.msg-transfer-footer {
    padding: 0 !important;
    color: transparent !important;
}
/* 此部分代码from🍓小Q怡🍫宝宝*/
.msg-transfer-card.msg-transfer-success {
  background: var(--transfer-card-bg-received) !important;
  background-color: var(--transfer-card-bg-received) !important;
}
.msg-transfer-card.msg-transfer-success .msg-transfer-icon {
  background-image: var(--transfer-icon-received) !important;
}
.msg-transfer-card.msg-transfer-rejected {
  background: var(--transfer-card-bg-received) !important;
  background-color: var(--transfer-card-bg-received) !important;
}
.msg-transfer-card.msg-transfer-rejected .msg-transfer-icon {
  background-image: var(--transfer-icon-returned) !important;
}
.msg-transfer-card.msg-transfer-expired-card {
  background: var(--transfer-card-bg-expired) !important;
  background-color: var(--transfer-card-bg-expired) !important;
}
.msg-transfer-card.msg-transfer-expired-card .msg-transfer-icon{
  background-image: var(--transfer-icon-expired) !important;
}
.msg-transfer-card.msg-transfer-expired-card .msg-transfer-expiry{
  display: none !important;
}

