.msg-redpacket-card {
    width: 232px !important;
    height: 82px !important; /* 高度微窄 */
    background: #FA9D3B !important; /* 👈 改这里：把原本暗暗的 #E08C36 改成亮橙色 #FA9D3B */
    border-radius: 6px !important;
    padding: 0 !important;
    position: relative !important;
    border: none !important;
    box-shadow: none !important;
    display: block !important;
}
/* 隐藏所有多余的转账元素，彻底剥离转账痕迹 */
.msg-redpacket-card::before,
.msg-redpacket-card::after,
.msg-redpacket-card .msg-transfer-amount,
.msg-redpacket-card .msg-transfer-footer,
.msg-redpacket-card .msg-transfer-status-text::before,
.msg-redpacket-card .msg-transfer-icon {
    display: none !important;
}

/* 1. 左上角红包贴图 (调用专门的红包装饰元素) */
.msg-redpacket-emoji {
    display: block !important;
    position: absolute !important;
    top: 18px !important;
    left: 14px !important;
    width: 30px !important;
    height: 40px !important;
    font-size: 0 !important; /* 隐藏原本的系统 emoji 字体 */
    background-image: url('https://i.imgant.com/v2/izowiCJ.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    z-index: 2 !important;
}

/* 2. 贴图右侧的备注文字：强行改为“恭喜发财 大吉大利” */
.msg-redpacket-card .msg-transfer-label {
    display: block !important;
    position: absolute !important;
    top: 25px !important;
    left: 55px !important;
    font-size: 0 !important; /* 隐藏原文字 */
    color: transparent !important;
    margin: 0 !important;
    padding: 0 !important;
}
.msg-redpacket-card .msg-transfer-label::after {
    content: "恭喜发财 大吉大利" !important;
    font-size: 15px !important;
    color: #FFFFFF !important;
    font-weight: 500 !important;
    display: block !important;
    white-space: nowrap !important;
}

/* 3. 左下方写着“红包” */
.msg-redpacket-card::after {
    content: "红包" !important;
    display: block !important;
    position: absolute !important;
    left: 14px !important;
    bottom: 8px !important;
    font-size: 11px !important;
    color: rgba(255, 255, 255, 0.75) !important;
    font-weight: normal !important;
    top: auto !important;
}

/* 4. 右下方写着转账人，自动读取身份 */
.msg-redpacket-card .msg-transfer-status-text {
    display: block !important;
    position: absolute !important;
    right: 14px !important;
    bottom: 8px !important;
    font-size: 0 !important; /* 隐藏原文字 */
    color: transparent !important;
    margin: 0 !important;
    padding: 0 !important;
    height: auto !important;
    width: auto !important;
    background: transparent !important;
}
.msg-me .msg-redpacket-card .msg-transfer-status-text::after {
    content: var(--user-name, "我") !important;
    font-size: 11px !important;
    color: rgba(255, 255, 255, 0.75) !important;
    font-weight: normal !important;
}
.msg-them .msg-redpacket-card .msg-transfer-status-text::after {
    content: var(--char-name, "对方") !important;
    font-size: 11px !important;
    color: rgba(255, 255, 255, 0.75) !important;
    font-weight: normal !important;
}

/* 5. 拆开后的状态颜色反馈 */
.msg-redpacket-card.is-opened {
    background: #FBE6D4 !important;
}
.msg-redpacket-card.is-opened .msg-transfer-label::after {
    color: #D9A071 !important;
}
.msg-redpacket-card.is-opened::after,
.msg-me .msg-redpacket-card.is-opened .msg-transfer-status-text::after,
.msg-them .msg-redpacket-card.is-opened .msg-transfer-status-text::after {
    color: rgba(217, 160, 113, 0.75) !important;
}
