/* ================= 排他规则：卡片、图片绝不显示贴纸与尾巴（已保护引用） ================= */
.bubble-me-custom:has(.msg-image-wrapper)::after,
.bubble-them-custom:has(.msg-image-wrapper)::after,
.bubble-me-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::after,
.bubble-them-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::after,
.bubble-me-custom:has([class*="card"])::after,
.bubble-them-custom:has([class*="card"])::after,
.bubble-me-custom:has([class*="transfer"])::after,
.bubble-them-custom:has([class*="transfer"])::after,
.bubble-me-custom:has(.gift-ig-container)::after,
.bubble-them-custom:has(.gift-ig-container)::after,
.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::before,
.bubble-them-custom:has(img:not(.msg-reply-block img):not(.voice-waveform img))::before,
.bubble-me-custom:has([class*="card"])::before,
