/*  卡片容器本体绝不单独生成尾巴 */
.msg-image-wrapper::after,
.msg-transfer-card::after,
.msg-loc-card::after,
.gift-ig-container::after,
.msg-theater-card::after,
.msg-offline-invite-card::after,
.msg-couples-invite-card::after,
.msg-couples-response-card::after,
.msg-werewolf-card::after,
.msg-mahjong-card::after,
